const p = msg.payload;
if (!p || typeof p !== 'object') { node.error('Objet JSON requis', msg); return null; }
const names = ['air_temperature_k','process_temperature_k','rotational_speed_rpm','torque_nm','tool_wear_min'];
if (!['L','M','H'].includes(p.type) || !p.message_id || !p.machine_id || !p.sent_at) { node.error('Champs obligatoires invalides',msg); return null; }
for (const key of names) { if (typeof p[key] !== 'number' || !Number.isFinite(p[key]) || p[key] < 0) { node.error('Mesure invalide: '+key,msg); return null; } }
msg.url = env.get('API_URL') + '/api/telemetry';
msg.headers = {'Content-Type':'application/json'};
